// Generated by tools/sync-wordpress-plugin.mjs from wordpress-plugin/plazo: do not edit by hand.
export const PLUGIN_FILES: Record<string, string> = {
  "assets/plazo.css": "/* Plazo · formulaire de réservation : sobre, il prend la police du site ; la couleur des boutons vient des réglages. */\n.plazo-form { --plazo-accent: #1E5E2E; display: grid; gap: 12px; max-width: 560px; }\n.plazo-form label { display: grid; gap: 4px; font-weight: 600; font-size: 0.95em; }\n.plazo-form input, .plazo-form textarea { width: 100%; box-sizing: border-box; padding: 8px 10px; border: 1px solid #c8ccd0; border-radius: 8px; font: inherit; }\n.plazo-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n@media (max-width: 480px) { .plazo-row { grid-template-columns: 1fr; } }\n.plazo-quote { margin: 0; font-weight: 600; color: var(--plazo-accent); min-height: 1.4em; }\n.plazo-button { background: var(--plazo-accent); color: #fff; border: 0; border-radius: 999px; padding: 12px 20px; font: inherit; font-weight: 700; cursor: pointer; }\n.plazo-button[disabled] { opacity: 0.6; cursor: wait; }\n.plazo-result { margin: 0; font-weight: 600; min-height: 1.4em; }\n.plazo-by { margin: 0; font-size: 0.8em; opacity: 0.7; }\n.plazo-trap { position: absolute; left: -9999px; width: 1px; height: 1px; }\n.plazo-done .plazo-button { display: none; }\n",
  "assets/plazo.js": "/* Plazo · formulaire de réservation du site du parking (19/11/2026). Talks to WordPress (admin-ajax), never to Plazo. */\n(function () {\n  'use strict';\n  var MESSAGES = {\n    full: 'Complet à ces dates : choisissez d’autres dates ou appelez le parking.',\n    no_price: 'Ce séjour ne peut pas être réservé en ligne : appelez le parking.',\n    return_before_arrival: 'Le retour doit être après le dépôt.',\n    in_the_past: 'La date de dépôt est passée.',\n    invalid_datetime: 'Vérifiez les dates et les heures.',\n    required: 'Remplissez les champs obligatoires.',\n    invalid_phone: 'Vérifiez le numéro de téléphone.',\n    invalid_email: 'Vérifiez l’adresse e-mail.',\n    expired: 'La page a expiré : rechargez-la.',\n    invalid_site_key: 'Le formulaire n’est pas relié à Plazo : prévenez le parking.',\n    operator_inactive: 'Les réservations en ligne sont fermées pour le moment.',\n    too_many_requests: 'Trop d’essais : réessayez dans quelques minutes.',\n    network: 'Plazo ne répond pas : réessayez dans un instant.'\n  };\n  var euro = function (cents) {\n    return (cents / 100).toLocaleString('fr-FR', { style: 'currency', currency: 'EUR' });\n  };\n  var messageOf = function (body) {\n    if (body && body.fields) {\n      for (var key in body.fields) {\n        if (MESSAGES[body.fields[key]]) return MESSAGES[body.fields[key]];\n      }\n      return MESSAGES.required;\n    }\n    return (body && MESSAGES[body.code]) || 'La réservation n’a pas pu être enregistrée : réessayez ou appelez le parking.';\n  };\n  var post = function (action, data) {\n    var form = new FormData();\n    form.append('action', action);\n    form.append('nonce', window.plazoSite.nonce);\n    Object.keys(data).forEach(function (k) { form.append(k, data[k]); });\n    return fetch(window.plazoSite.ajaxUrl, { method: 'POST', body: form, credentials: 'same-origin' }).then(function (r) {\n      return r.json().catch(function () { return {}; }).then(function (body) { return { ok: r.ok, body: body }; });\n    }, function () { return { ok: false, body: { code: 'network' } }; });\n  };\n\n  document.querySelectorAll('.plazo-form').forEach(function (form) {\n    var quote = form.querySelector('.plazo-quote');\n    var result = form.querySelector('.plazo-result');\n    var button = form.querySelector('.plazo-button');\n    var stay = function () {\n      var f = form.elements;\n      if (!f.arrivalDate.value || !f.returnDate.value) return null;\n      return {\n        arrivalAt: f.arrivalDate.value + 'T' + (f.arrivalTime.value || '08:00'),\n        returnAt: f.returnDate.value + 'T' + (f.returnTime.value || '18:00')\n      };\n    };\n    var available = false;\n    var refresh = function () {\n      var s = stay();\n      available = false;\n      if (!s) { quote.textContent = ''; return; }\n      quote.textContent = 'Recherche des places…';\n      post('plazo_quote', s).then(function (r) {\n        if (r.ok && r.body.available) {\n          available = true;\n          quote.textContent = r.body.days + ' jour' + (r.body.days > 1 ? 's' : '') + ' · ' + euro(r.body.priceCents) + ', à payer au parking';\n        } else {\n          quote.textContent = r.ok ? MESSAGES[r.body.reason] || MESSAGES.no_price : messageOf(r.body);\n        }\n      });\n    };\n    ['arrivalDate', 'arrivalTime', 'returnDate', 'returnTime'].forEach(function (name) {\n      form.elements[name].addEventListener('change', refresh);\n    });\n    form.addEventListener('submit', function (event) {\n      event.preventDefault();\n      var s = stay();\n      if (!s) { result.textContent = MESSAGES.invalid_datetime; return; }\n      var f = form.elements;\n      var data = Object.assign({}, s, {\n        firstName: f.firstName.value,\n        lastName: f.lastName.value,\n        phone: f.phone.value,\n        email: f.email.value,\n        plate: f.plate.value,\n        returnFlight: f.returnFlight.value,\n        passengers: f.passengers.value,\n        message: f.message.value,\n        website: f.website.value\n      });\n      button.disabled = true;\n      result.textContent = 'Enregistrement…';\n      post('plazo_book', data).then(function (r) {\n        button.disabled = false;\n        if (r.ok && r.body.reference) {\n          form.classList.add('plazo-done');\n          result.textContent = 'Réservation enregistrée, référence ' + r.body.reference + '. Le parking vous attend.';\n        } else {\n          result.textContent = messageOf(r.body);\n        }\n      });\n    });\n  });\n})();\n",
  "plazo.php": "<?php\n/**\n * Plugin Name: Plazo\n * Description: Le formulaire de réservation de votre parking, relié à Plazo Pro : places et prix du moment, réservation directement dans votre planning.\n * Version: 1.0.0\n * Requires at least: 5.8\n * Requires PHP: 7.4\n * Author: Benford Tech\n * Author URI: https://pro.plazo.fr\n * License: GPLv2 or later\n * Text Domain: plazo\n */\n\nif (!defined('ABSPATH')) {\n    exit;\n}\n\ndefine('PLAZO_VERSION', '1.0.0');\ndefine('PLAZO_API_BASE', 'https://www.plazo.fr/api');\n\n/** The API's address: the constant, unless the site sets PLAZO_API_URL in wp-config.php (tests). */\nfunction plazo_api_base()\n{\n    return defined('PLAZO_API_URL') ? rtrim(PLAZO_API_URL, '/') : PLAZO_API_BASE;\n}\n\n/** One call to Plazo with the site's key; returns [status, decoded body]. The key never leaves the server. */\nfunction plazo_request($method, $path, $body = null)\n{\n    $key = trim((string) get_option('plazo_site_key', ''));\n    if ($key === '') {\n        return array(0, array('code' => 'no_key'));\n    }\n    $args = array(\n        'method' => $method,\n        'timeout' => 15,\n        'headers' => array(\n            'X-Plazo-Site-Key' => $key,\n            'X-Plazo-Site-Url' => home_url('/'),\n            'Accept' => 'application/json',\n        ),\n    );\n    if ($body !== null) {\n        $args['headers']['Content-Type'] = 'application/json';\n        $args['body'] = wp_json_encode($body);\n    }\n    $response = wp_remote_request(plazo_api_base() . $path, $args);\n    if (is_wp_error($response)) {\n        return array(0, array('code' => 'network'));\n    }\n    $decoded = json_decode(wp_remote_retrieve_body($response), true);\n    return array((int) wp_remote_retrieve_response_code($response), is_array($decoded) ? $decoded : array());\n}\n\n// ---- Réglages › Plazo ---------------------------------------------------------------------------------------------------\n\nadd_action('admin_menu', function () {\n    add_options_page('Plazo', 'Plazo', 'manage_options', 'plazo', 'plazo_settings_page');\n});\n\nadd_action('admin_init', function () {\n    register_setting('plazo', 'plazo_site_key', array('type' => 'string', 'sanitize_callback' => 'sanitize_text_field'));\n    register_setting('plazo', 'plazo_accent', array('type' => 'string', 'sanitize_callback' => 'sanitize_hex_color', 'default' => '#1E5E2E'));\n});\n\nfunction plazo_settings_page()\n{\n    if (!current_user_can('manage_options')) {\n        return;\n    }\n    $status = null;\n    if (trim((string) get_option('plazo_site_key', '')) !== '') {\n        list($code, $body) = plazo_request('GET', '/public/site/status');\n        $status = $code === 200 ? $body : array('error' => isset($body['code']) ? $body['code'] : 'error');\n    }\n    ?>\n    <div class=\"wrap\">\n        <h1>Plazo</h1>\n        <p>Collez la clé de votre parking, que vous trouvez dans Plazo Pro, <strong>Parking › Réglages › Site du parking</strong>.</p>\n        <?php if (is_array($status) && isset($status['connected'])) : ?>\n            <div class=\"notice notice-success inline\"><p>Connecté à <strong><?php echo esc_html($status['parkingName']); ?></strong>.</p></div>\n        <?php elseif (is_array($status)) : ?>\n            <div class=\"notice notice-error inline\"><p>La clé n'est pas reconnue par Plazo. Vérifiez-la, ou créez-en une nouvelle dans Plazo Pro.</p></div>\n        <?php endif; ?>\n        <form method=\"post\" action=\"options.php\">\n            <?php settings_fields('plazo'); ?>\n            <table class=\"form-table\" role=\"presentation\">\n                <tr>\n                    <th scope=\"row\"><label for=\"plazo_site_key\">Clé Plazo</label></th>\n                    <td><input name=\"plazo_site_key\" id=\"plazo_site_key\" type=\"password\" class=\"regular-text\" autocomplete=\"off\" value=\"<?php echo esc_attr(get_option('plazo_site_key', '')); ?>\"></td>\n                </tr>\n                <tr>\n                    <th scope=\"row\"><label for=\"plazo_accent\">Couleur des boutons</label></th>\n                    <td><input name=\"plazo_accent\" id=\"plazo_accent\" type=\"text\" class=\"small-text\" value=\"<?php echo esc_attr(get_option('plazo_accent', '#1E5E2E')); ?>\"> <span class=\"description\">Par exemple #0E4C6E.</span></td>\n                </tr>\n            </table>\n            <?php submit_button('Enregistrer'); ?>\n        </form>\n        <h2>Afficher le formulaire</h2>\n        <p>Collez ce code dans la page de votre choix (bloc « Code court ») :</p>\n        <p><code>[plazo_reservation]</code></p>\n        <p>Les réservations arrivent tout de suite dans le planning de Plazo Pro, au canal « Site du parking ». Le client paie au parking.</p>\n    </div>\n    <?php\n}\n\n// ---- Le formulaire --------------------------------------------------------------------------------------------------------\n\nadd_shortcode('plazo_reservation', function () {\n    wp_enqueue_style('plazo', plugins_url('assets/plazo.css', __FILE__), array(), PLAZO_VERSION);\n    wp_enqueue_script('plazo', plugins_url('assets/plazo.js', __FILE__), array(), PLAZO_VERSION, true);\n    wp_localize_script('plazo', 'plazoSite', array(\n        'ajaxUrl' => admin_url('admin-ajax.php'),\n        'nonce' => wp_create_nonce('plazo'),\n    ));\n    $accent = sanitize_hex_color(get_option('plazo_accent', '#1E5E2E'));\n    if (!$accent) {\n        $accent = '#1E5E2E';\n    }\n    ob_start();\n    ?>\n    <form class=\"plazo-form\" style=\"--plazo-accent: <?php echo esc_attr($accent); ?>\" novalidate>\n        <div class=\"plazo-row\">\n            <label>Dépôt <input type=\"date\" name=\"arrivalDate\" required></label>\n            <label>Heure <input type=\"time\" name=\"arrivalTime\" value=\"08:00\" required></label>\n        </div>\n        <div class=\"plazo-row\">\n            <label>Retour <input type=\"date\" name=\"returnDate\" required></label>\n            <label>Heure <input type=\"time\" name=\"returnTime\" value=\"18:00\" required></label>\n        </div>\n        <p class=\"plazo-quote\" aria-live=\"polite\"></p>\n        <div class=\"plazo-row\">\n            <label>Prénom <input type=\"text\" name=\"firstName\" autocomplete=\"given-name\" required></label>\n            <label>Nom <input type=\"text\" name=\"lastName\" autocomplete=\"family-name\" required></label>\n        </div>\n        <div class=\"plazo-row\">\n            <label>Téléphone mobile <input type=\"tel\" name=\"phone\" autocomplete=\"tel\" required></label>\n            <label>E-mail <input type=\"email\" name=\"email\" autocomplete=\"email\"></label>\n        </div>\n        <div class=\"plazo-row\">\n            <label>Plaque <input type=\"text\" name=\"plate\" placeholder=\"AB-123-CD\"></label>\n            <label>Vol retour <input type=\"text\" name=\"returnFlight\" placeholder=\"TO 3627\"></label>\n        </div>\n        <div class=\"plazo-row\">\n            <label>Passagers <input type=\"number\" name=\"passengers\" min=\"1\" max=\"9\" value=\"1\"></label>\n        </div>\n        <label>Message <textarea name=\"message\" rows=\"2\" maxlength=\"300\"></textarea></label>\n        <input type=\"text\" name=\"website\" class=\"plazo-trap\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\">\n        <button type=\"submit\" class=\"plazo-button\">Réserver</button>\n        <p class=\"plazo-result\" role=\"status\" aria-live=\"polite\"></p>\n        <p class=\"plazo-by\">Réservation gérée avec Plazo · paiement au parking</p>\n    </form>\n    <?php\n    return ob_get_clean();\n});\n\n/** The JSON answer of an AJAX call; a nonce that fails or the trap field filled ends here. */\nfunction plazo_ajax_guard()\n{\n    if (!check_ajax_referer('plazo', 'nonce', false)) {\n        wp_send_json(array('code' => 'expired'), 403);\n    }\n    if (!empty($_POST['website'])) {\n        wp_send_json(array('code' => 'refused'), 400);\n    }\n}\n\nfunction plazo_ajax_quote()\n{\n    plazo_ajax_guard();\n    $query = http_build_query(array(\n        'arrivalAt' => sanitize_text_field(wp_unslash(isset($_POST['arrivalAt']) ? $_POST['arrivalAt'] : '')),\n        'returnAt' => sanitize_text_field(wp_unslash(isset($_POST['returnAt']) ? $_POST['returnAt'] : '')),\n    ));\n    list($code, $body) = plazo_request('GET', '/public/site/quote?' . $query);\n    wp_send_json($body, $code ? $code : 502);\n}\nadd_action('wp_ajax_plazo_quote', 'plazo_ajax_quote');\nadd_action('wp_ajax_nopriv_plazo_quote', 'plazo_ajax_quote');\n\nfunction plazo_ajax_book()\n{\n    plazo_ajax_guard();\n    $fields = array('arrivalAt', 'returnAt', 'firstName', 'lastName', 'phone', 'email', 'plate', 'returnFlight', 'passengers', 'message');\n    $booking = array();\n    foreach ($fields as $field) {\n        $value = isset($_POST[$field]) ? wp_unslash($_POST[$field]) : '';\n        $booking[$field] = $field === 'message' ? sanitize_textarea_field($value) : sanitize_text_field($value);\n    }\n    list($code, $body) = plazo_request('POST', '/public/site/bookings', $booking);\n    wp_send_json($body, $code ? $code : 502);\n}\nadd_action('wp_ajax_plazo_book', 'plazo_ajax_book');\nadd_action('wp_ajax_nopriv_plazo_book', 'plazo_ajax_book');\n",
  "readme.txt": "=== Plazo ===\nContributors: benfordtech\nTags: parking, réservation, aéroport, navette\nRequires at least: 5.8\nTested up to: 6.7\nRequires PHP: 7.4\nStable tag: 1.0.0\nLicense: GPLv2 or later\n\nLe formulaire de réservation de votre parking d'aéroport, relié à Plazo Pro.\n\n== Description ==\n\nLes clients choisissent leurs dates sur votre site : le formulaire montre si le parking a de la place et le prix de votre grille, puis la réservation arrive tout de suite dans le planning de Plazo Pro, au canal « Site du parking ». Le client paie au parking.\n\n== Installation ==\n\n1. Extensions › Ajouter › Téléverser l'extension : choisissez plazo.zip, puis Activer.\n2. Réglages › Plazo : collez la clé de votre parking (Plazo Pro, Parking › Réglages › Site du parking).\n3. Collez [plazo_reservation] dans la page « Réserver » de votre site.\n"
};
